/* Seasons of Mystery – „Ein Wintermärchen“ (Buch S. 68–87), deutscher Text. Aufbau wie som-teufel.js. */
window.VAE_MYS = window.VAE_MYS || {};
VAE_MYS.winter = {
 titel: "Ein Wintermärchen", buch: "vae_seasons", p: 68, zeit: "Winter", ort: "Ingermanland · Gasthaus Tammsalu",
 warnung: "Gewalt, Tod, Tod von Kindern", bild: "som/winter_eroeffnung",
 tabs: [["Hintergrund","hg"],["Anreise","an"],["Orte","orte"],["Konfrontation","kf"],["|"],["Figuren","fg"],["Hinweise","hw"],["Handouts","ho"],["Nachspiel","ns","end"]],
 pp: {hinter: 69, konf: 71, myth: 71, einl: 71, vorb: 72, reise: 72, ankunft: 72, karte: 74, cd: 75},

 hg: {
  vl: "Still sind die Wälder, groß und klein,<br>vom Frost in Weiß gehüllt,<br>nur der ferne Wasserfall<br>murmelt und summt in der Nacht.<br>Der Nisse lauscht und, halb im Traum,<br>meint, es sei der Zeiten stetiger Strom,<br>fragt sich, wohin er wohl fließt,<br>und aus welcher Quelle er kommt.<br><i>– Viktor Rydberg</i>",
  intro: "Die Charaktere erleiden einen Unfall, bleiben in der dunklen Kälte stecken und werden unter den glitzernden Wintersternen von einem geheimnisvollen Gegner herausgefordert.",
  vorspiel: "Dieser erste Abschnitt beschreibt den Hintergrund des Mysteriums und die Konflikte, auf denen es beruht. Eine Einladung eröffnet die Sitzung, gefolgt von einer Beschreibung der Reise der Charaktere von Sankt Petersburg in die tiefen Wälder im Herzen Ingermanlands, wo das Mysterium spielt. Der Abschnitt schließt mit einem Countdown von Ereignissen, den du als Spielleiter zu einem passenden Zeitpunkt im Mysterium in Gang setzt – und einer Katastrophe, die beschreibt, was geschieht, wenn die Spielercharaktere nicht handeln oder scheitern. Dieses Mysterium unterscheidet sich von den meisten anderen darin, dass die Spielercharaktere das Ziel der Einladung nie erreichen – ein geheimes Treffen von Menschen mit Wissen über übernatürliche Phänomene auf dem Gut des Grafen Konstantin Konstantinowitsch in Ingermanland. Auf der Reise durch den Wintersturm in den tiefen Wäldern Ingermanlands erleiden die Charaktere einen Unfall und finden sich im Gasthaus Tammsalu wieder, weit entfernt vom nächsten Dorf. Dort spielt dieses Mysterium.",
  hinter: [
   "Das Gasthaus Tammsalu ist seit der schwedischen Zeit im Besitz der Familie Trygg (siehe den Kasten auf S. 70). Die Familie verließ vor zweihundert Jahren ihr kleines Häuschen bei Falun und zog nach Ingermanland, um im „Wilden Osten“ ihr Glück zu suchen. In einem Birkenrindenschuh brachten sie eine Eichel vom Häuschen mit, die sie am kleinen Teich hinter dem Gasthaus pflanzten. Heute spenden die mächtigen Äste der Eiche in den Sommermonaten willkommenen Schatten. Anders als andere Schweden, die Ingermanland flohen, um den Kriegen zwischen Schweden und Russland zu entgehen, haben die Tryggs sich entschieden zu bleiben. Während des Krieges diente ihr Gasthaus als Feldlazarett.",
   "Die Menschen im Gasthaus Tammsalu sind im Wald für ihre Gastfreundschaft gegenüber Menschen und Tieren gleichermaßen bekannt. Trotz der bitteren Winter konnte ihr Betrieb stets warme Betten, Essen und Trinken bieten, und mancher Reisende hat hier Zuflucht vor den Schneestürmen gesucht. Das Gasthaus liegt günstig an einem öden Abschnitt der Straße zwischen Sankt Petersburg und Narva, und die Familie hat viele Reisende beherbergt. Ihr Geschäft blühte. Als Herr und Frau Trygg starben, übernahmen Axel und seine Schwester Ester die Leitung des Gasthauses. Axel träumte davon, das Geschäft auszubauen und abends Glücksspiel zur Unterhaltung der Gäste zuzulassen. Ester dagegen war entschlossen, das Gasthaus und seine Traditionen zu bewahren.",
   "Im Zentrum dieses Mysteriums steht ein Konflikt zwischen den unerbittlichen Kräften der Natur und der Sicherheit von Herd und Heim. In den Wintermonaten ist das Leben hier von Kälte, Schnee und Dunkelheit geprägt. Schwere Schneestürme plagen die Gegend, und die bittere Kälte ist ein schneller und gnadenloser Mörder. Kinder werden gewarnt, nicht allein in den Wald zu gehen. Die Dorfbewohner erzählen Geschichten über eine Verkörperung des Winters selbst, Morozko – oder Väterchen Frost. Morozko ist ein Winterdämon in Gestalt eines Mannes, der manchmal großzügig ist und den Menschen den Weg nach Hause zeigt, aber auch ihren Geist verdrehen und sie tief in die Kälte führen kann, wo sie erfrieren und sterben.",
   "Die Legenden erzählen auch von Schutzgeistern, die Menschen und Höfe vor der gnadenlosen Wildnis bewahren. Diese mächtigen Vaesen, die ihren Herd hüten und manchmal Glück bringen, heißen in der örtlichen Überlieferung Domovoi. Domovoi sind kleine alte Männer und Frauen in hellen oder dunklen Kleidern und Hüten, die über den Haushalt und sein Vieh wachen. Doch sie sind launisch und können Probleme verursachen, wenn sie verärgert oder vernachlässigt werden, weshalb die Menschen ihnen oft Essen am Kamin hinstellen. Domovoi sind Gestaltwandler, die sich in Katzen oder Wiesel verwandeln können. Sie halten zu ihrer Familie und können mit ihr in einem kleinen Birkenrindenschuh in ein neues Zuhause ziehen.",
   "Die Spielercharaktere von der Gesellschaft in Upsala kennen dieses Vaesen unter einem anderen Namen – Nisse (S. 148 im Grundregelwerk). Das Gasthaus und der Hof der Familie stehen unter dem Schutz eines Nisse namens Graufuß, der den Tryggs seit vielen Generationen folgt und mit ihnen im Birkenrindenschuh nach Ingermanland kam. Es ist sein Schutz, der das Gasthaus auch in den harten Wintermonaten gedeihen ließ.",
   "Im Frühling ein Jahr vor Beginn dieses Mysteriums wurde Ester tot am Rand des Teichs hinter dem Gasthaus gefunden. Sie hatte einen Schlaganfall erlitten, war bewusstlos ins Wasser gefallen und ertrunken. Seltsamerweise lag sie oben am Ufer, als hätte jemand sie aus dem Wasser gezogen. Es gab Gerüchte, sie sei ermordet worden. Bald darauf begannen auf dem Hof seltsame Dinge zu geschehen. Gegenstände verschwanden und tauchten an merkwürdigen Orten wieder auf, Menschen verletzten sich bei seltsamen Unfällen. Nachts hörte man im Haus seltsame Geräusche – Seufzer und Klicken in den Dielen, als bewege sich dort jemand oder etwas. Die Bewohner haben verschiedene Theorien darüber, was vor sich geht, aber in Wahrheit steckt der Nisse hinter den seltsamen Ereignissen und Unfällen auf dem Hof.",
   "Der Nisse Graufuß ist uralt. Menschengenerationen sind für ihn wie die Jahreszeiten – Kinder werden geboren, wachsen auf, bekommen eigene Kinder, werden alt und sterben. Für ihn ist der Strom der Menschen, die kommen und gehen, wie ein Fluss. Er kümmert sich selten um jemanden. Doch Ester war anders. Sie bemerkte Graufuß und sprach als Mädchen mit ihm, und als sie heranwuchs, vergaß sie ihren Freund nie. Jeden Morgen stellte sie kleine Brocken Brot, Milch oder Brei am Ofen hin. Zum ersten Mal seit Jahrhunderten gewann Graufuß einen Menschen lieb, und seine Liebe zu Ester war tief. Er fürchtete, sie würde eines Tages verheiratet werden und den Hof verlassen.",
   "Eines Morgens sah Graufuß, wie Ester zusammenbrach und in den Teich fiel, getroffen von einem Schlaganfall wie viele in ihrer Familie vor ihr. Er schaffte es, sie ans Ufer zu ziehen, konnte sie aber nicht ins Leben zurückholen. Esters Tod traf ihn schwer. Zum ersten Mal in seinem Leben fühlte es sich wie ein Fluch an, dass ein Menschenleben nur ein Wimpernschlag im Vergleich zu seinem eigenen war, und Graufuß wurde von Trauer überwältigt.",
   "Der Nisse sorgt sich auch, dass so wenige Menschen noch den alten Bräuchen folgen. Die Domovoi geraten in Vergessenheit, während die jüngeren Generationen heranwachsen und die alten Traditionen durch neue ersetzt werden. Nun glaubt auf dem Hof niemand mehr an den Nisse, und niemand stellt ihm Gaben hin oder zeigt ihm Wertschätzung. Graufuß’ Trauer wandelte sich in Zorn, den er auslebt, indem er Ärger und Unfälle verursacht und seine schützende Hand vom Hof zurückzieht. Gäste beklagen sich über Gegenstände, die auf sie herabfallen, und es heißt, auf dem Hof spuke es. Axel ist unglücklich, hat das Gasthaus aber offen gehalten."
  ],
  kaesten: [
   {t:"Ingermanland und die vergessenen Völker", p:70, x:"Das Gasthaus Tammsalu liegt in der historischen Region Ingermanland, Teil des Gouvernements Sankt Petersburg zwischen dem Ladogasee und dem Peipussee im Westen Russlands. Ingermanland, manchmal als „Wilder Osten“ bezeichnet, war bis ins 18. Jahrhundert ein schwedisches Herrschaftsgebiet, bevor es an Russland abgetreten und umbenannt wurde. Die Kriege und der Bau von Sankt Petersburg trieben einen Teil der Bevölkerung aus der Gegend, andere zogen dorthin, um religiöser Verfolgung, Leibeigenschaft oder Steuern zu entgehen. Einwanderung und die Deportation von Verbrechern in die Region führten zu einer Mischung aus verschiedenen Kulturen, Sprachen und Religionen. Die Ureinwohner Ingermanlands waren Finno-Ugrier, die die finno-ugrischen Sprachen Ingrisch und Wotisch sprachen, die heute fast ausgestorben sind. Diese Volksgruppen wurden „die vergessenen Völker“ genannt."}
  ],
  mythic: "Wenn du dieses Mysterium statt im Mythischen Norden im Mythischen Britannien und Irland spielen möchtest, ändere das Ziel der Einladung auf das Dorf Aviemore in den Cairngorms, fast 160 Kilometer nördlich von Edinburgh. Die Reise über das Cairngorm-Gebirge und durch die Wälder rund um Loch an Eilein führt sie in wilde Umwege, und hier finden sie das Gasthaus Ben Macdui. Denke auch daran, die Namen der Nichtspielercharaktere zu ändern.",
  konflikt: [
   "Der Hauptkonflikt dieses Mysteriums besteht zwischen dem Nisse Graufuß und Axel Trygg – der nicht begreift, was vor sich geht, da er nicht an Nisse und solchen „alten Aberglauben“ glaubt. Axel hat den Nisse vernachlässigt, seit Ester starb, und in seiner Trauer und Wut hat Graufuß begonnen, Ärger zu machen. Sein Zorn wächst, und wenn Gäste ankommen, zieht er in die Sauna. Wenn Axel ihn weiter vernachlässigt, wird er anfangen, Unfälle zu verursachen, und schließlich den Hof verlassen. Ohne ihn sind die Menschen dort Väterchen Frost schutzlos ausgeliefert, und alle im Gasthaus Tammsalu riskieren, in der bitteren Kälte zu erfrieren.",
   "Der Nebenkonflikt ist der zwischen unterschiedlichen Sichtweisen auf die unnatürlichen Ereignisse in Tammsalu. Die Untersuchungen der Unfälle im Gasthaus erzeugen einen Konflikt unter den Reisenden, die dort Zuflucht gesucht haben. Die Gäste haben verschiedene Erklärungen für das Geschehen, und diese können den Spielercharakteren entweder helfen oder sie in die Irre führen. Lösen die Spielercharaktere das Mysterium nicht und überzeugen die anderen nicht von dem, was vor sich geht, wird die Lage zunehmend hitziger. Gastwirt Axel weiß nicht, was er tun oder wem er glauben soll. Das Herumschnüffeln der Spielercharaktere auf dem Hof kann den Nisse noch wütender machen. Führen ihre Nachforschungen zur Schändung von Esters Grab, steigert sich sein mutwilliges Verhalten zu offener Gewalt."
  ]
 },

 an: {
  hoName: "Handout 4A", karten: ["winter_karte_uebersicht", "winter_karte_tammsalu"],
  einladung: [
   "Dieses Mysterium beginnt damit, dass die Gesellschaft einen Brief erhält, der sie zu dem geheimen Treffen Conclavum Sub Rosa einlädt, das Graf Konstantin Konstantinowitsch veranstaltet. Es ist eine Zusammenkunft, zu der sorgfältig ausgewählte Teilnehmer aus ganz Europa kommen, um Erfahrungen und Wissen über die Erforschung übernatürlicher Phänomene auszutauschen. Das Treffen findet auf dem Gut des Grafen in den Wäldern südwestlich von Sankt Petersburg statt. Der Brief (Handout 4A) liegt als Handout am Ende dieses Buches bei und ist auf der Webseite von Free League zum Herunterladen verfügbar. Er lautet:",
   "Beachte, dass die Spielercharaktere das Treffen des Grafen Konstantinowitsch nie erreichen werden, da sie auf dem Weg dorthin einen Unfall erleiden und stattdessen im Gasthaus Tammsalu landen (mehr dazu unten)."
  ],
  brief: {
   t1: "An wen es betrifft,",
   x: ["mein Name ist Konstantin Konstantinowitsch, Graf von Jamburg in Ingermanland, westlich von Sankt Petersburg im Russischen Reich. Der Ruf Eurer Gesellschaft ist weit und breit bekannt unter denen, die das Unsichtbare beobachten und das Unerklärliche verstehen wollen. Ich habe den größten Respekt vor Eurer Arbeit und suche, wie Ihr, Antworten auf die Rätsel des Kosmos.",
       "Zur Mittwinter-Blotfeier veranstalte ich eine Zusammenkunft, die Euch meiner Ansicht nach interessieren dürfte – Conclavum Sub Rosa. Das Treffen bringt Menschen unterschiedlicher Herkunft zusammen, die ein gemeinsames Interesse am Übernatürlichen haben und durch den Prozess der Alchemie ein tieferes Verständnis suchen.",
       "Es wäre mir eine große Ehre und Freude, wenn die Gesellschaft unsere Versammlung mit ihrer Anwesenheit beehren würde. Ich erwarte Euch am zwanzigsten Dezember in meiner Residenz vor Jamburg, um die Geheimnisse und Rätsel des Lebens zu besprechen.",
       "Hochachtungsvoll,<br>Graf Konstantin Konstantinowitsch",
       "PS. Alles ist miteinander verbunden!"],
   sig: ""
  },
  vorb: ["Wie üblich können sich die Spielercharaktere in ihrem Hauptquartier auf die Reise vorbereiten und dadurch einen Vorteil erhalten (siehe Kapitel 9 im Grundregelwerk).",
         "Spielercharaktere, die in Upsala nach Informationen über Conclavum Sub Rosa und Graf Konstantin Konstantinowitsch suchen, finden heraus, dass er für seine fantasievollen Märchen, Gedichte und seine Studien des Übernatürlichen bekannt ist. Mehr Informationen sind nicht zu finden."],
  kaesten: [
   {t:"Sprachen", p:72, x:"In diesem Mysterium treffen die Spielercharaktere auf Nichtspielercharaktere, die eine andere Muttersprache sprechen als sie selbst. Um es einfach zu halten, empfehlen wir anzunehmen, dass die Spielercharaktere in mehreren Sprachen bewandert sind und sich daher frei mit allen unterhalten können, denen sie begegnen."},
   {t:"Der Kälte widerstehen", p:73, x:"Eine Spielerfigur, die schwerer Kälte ausgesetzt ist, muss in regelmäßigen Abständen Proben auf KRAFT ablegen. Es funktioniert wie eine Furchtprobe gegen Furcht 1 (S. 68 im Grundregelwerk), nur dass die Probe mit KRAFT gewürfelt wird und ein Misserfolg zusätzlich zur normalen Wirkung (ein geistiger Zustand und vorübergehender Kontrollverlust) einen körperlichen Zustand zur Folge hat. Wer von der Kälte Gebrochen wird, muss weiter Proben auf KRAFT ablegen und erfriert beim nächsten Misserfolg. Die Wirkung der Kälte hält an, bis das Opfer wieder in die Wärme gelangt. Spielerfiguren, die der Kälte nicht widerstehen, können, wenn es passt, auch eine Vision von Väterchen Frost haben – siehe das Beispiel im Kasten Ein Mittwinternachtstraum auf S. 74."}
  ],
  reise: ["Die Bootsfahrt nach Sankt Petersburg verläuft ereignislos (es sei denn, du willst es anders). An Bord des Schiffes können die Spielercharaktere ihre Zeit damit verbringen, zu lernen oder die Rede vorzubereiten, um die sie für die Versammlung des Grafen Konstantinowitsch gebeten wurden."],
  ankunft: ["Als die Spielercharaktere am Kai in Sankt Petersburg an Land gehen, beginnt es zu schneien. Die Luft ist kühl, und bald finden sie die Postkutsche, die sie nach Narva und zum Gut Konstantinowitschs bringen wird. Neben der Kutsche steht Kutscher Ilya Jermakow (S. 73). Ruhig, aber höflich lädt er das Gepäck der Gruppe auf das Kutschdach, während sie drinnen Platz nehmen. Der erste Halt liegt im Zentrum von Sankt Petersburg. Beim berühmten Restaurant Talon unten am Fluss Newa steigt eine einzelne Adlige in die Kutsche. Sie ist Schwedin und stellt sich als Vilma af Zimt vor (S. 74). Der Kutscher lädt ihr Gepäck auf, und die Fahrt geht weiter, fort vom Hafen und den Palästen und Kirchen der Stadt, hinaus aufs Land.",
   "Vilma af Zimt ist ebenfalls auf dem Weg zu Graf Konstantinowitsch, was sie den Spielercharakteren auf Nachfrage erzählt. Wollen sie mehr über sie wissen, kann sie ihnen alles erzählen, was in ihrer Charakterbeschreibung steht. Die Zeit vergeht, es wird dunkel, und draußen sinkt die Temperatur schnell. Matte Lichter sind zwischen den fernen Häusern zu sehen, immer weniger, je weiter sie kommen. Es wird kälter, und die Spielercharaktere sind dankbar, unter den Pelzen in der Kutsche zusammengekauert zu sitzen. Der Frost bildet schöne Muster auf den kleinen Glasfenstern der Postkutsche. Stunden vergehen. Die Kutsche schwankt und schaukelt, und schließlich gibt es draußen vor dem Fenster nichts als endlose Tannen. Einige der Spielercharaktere dösen ein.",
   "Plötzlich hören die Charaktere die Pferde wiehern und den Kutscher laut auf Russisch fluchen. Die Kutsche schaukelt heftig, und ohne Vorwarnung werden die Charaktere heftig herumgeschleudert, als die Kutsche umkippt und einen Hang hinabrollt. Jede Spielerfigur muss eine Probe auf BEWEGLICHKEIT ablegen – wer scheitert, wird aus der Kutsche geschleudert. Alle Spielerfiguren erleiden Schaden durch den Sturz – der Angriff wird für diejenigen, die in der Kutsche bleiben, mit drei Würfeln gewürfelt, für die herausgeschleuderten mit sechs. Vilma af Zimt hat Glück und kommt nur mit einer Beule am Kopf davon (ein körperlicher Zustand). Ilya bleibt völlig unverletzt.",
   "Nach dem Unfall, der dadurch verursacht wurde, dass die Kutsche auf eine Wurzel auflief, lässt sie sich nicht mehr bewegen. Sie liegt in einer großen Schneewehe am Straßenrand, das ganze Gepäck verstreut auf dem Boden. Als die Charaktere wieder zu sich kommen, sehen sie nichts als den Nebel ihres Atems und das Sternenlicht, das vom dunklen Winterhimmel herabscheint. Es ist so kalt, dass das Atmen schmerzt. Tief im Wald heult ein Wolf. Jeder Atemzug gefriert zu Wolken aus Eiskristallen. Der Schnee fällt immer dichter, und der Wind nimmt zu.",
   "Ilya sagt, er kenne einen Ort, an dem die Charaktere Zuflucht für die Nacht finden können. „Wir müssen zum Gasthaus Tammsalu, nicht weit von hier, sonst überleben wir die Nacht nicht.“ Jede Spielerfigur kann nur einen Gegenstand ihrer Wahl mitnehmen – der Rest liegt im Schnee verstreut. Für jeden weiteren Gegenstand, den sie suchen wollen, müssen sie eine Probe auf KRAFT bestehen, um die schwere Kälte zu ertragen (siehe den Kasten auf S. 72). Vilma af Zimt lässt mehrere Gegenstände in der Kutsche zurück. Eines der Pferde hat ein verletztes Hinterbein und humpelt stark. Verweilen die Charaktere zu lange bei der Kutsche, erfriert das verletzte Pferd.",
   "Ilya übernimmt die Führung und hält seine Laterne hoch, um den Weg entlang der verschneiten Straße zu beleuchten. Nach einem zermürbenden Marsch (jede Spielerfigur legt eine weitere Probe auf KRAFT ab, um der Kälte zu widerstehen) erreichen sie das Gasthaus, umgeben von tiefem Kiefernwald, viele Stunden vom nächsten Dorf entfernt. Der Sturm ist heftig, und die Charaktere können kaum die Person vor sich sehen. Müde und zerschlagen betritt die Gruppe das Gasthaus Tammsalu. Der Kutscher geht in den Stall, um sich um die Pferde zu kümmern. Im Speisesaal können die Charaktere Gastwirt Axel Trygg, sein Personal und andere Gäste treffen (siehe die Liste auf S. 77). Der Sturm draußen wird stärker, und die Straße ist eingeschneit. Die Spielercharaktere sitzen im Gasthaus fest."]
 },

 cdIntro: "In diesem Mysterium müssen die Spielercharaktere zusammenarbeiten, um herauszufinden, wer die Unfälle verursacht. Es gibt falsche Spuren, etwa die Brüder Campbell (S. 78), die glauben, dass ein Wiedergänger hinter allem steckt. Verdacht kann auch auf Kutscher Ilya fallen, dessen Werbung um Ester abgewiesen wurde. Gehen die Spielercharaktere bei ihren Ermittlungen in die falsche Richtung, riskieren sie, den Nisse noch weiter aufzubringen – bis er schließlich den Hof und seine Menschen ihrem Schicksal im frostigen Winter überlässt. Dann sind sie alle der bitteren Kälte schutzlos ausgeliefert und stehen Väterchen Frost hilflos gegenüber. Mit den folgenden Ereignissen kannst du bei Bedarf das Tempo des Spiels erhöhen und die Spieler zur abschließenden Konfrontation drängen:",
 cd: [
  {n:"Kalter Morgen", x:"Am ersten Morgen wachen die Spielercharaktere in einem eiskalten Haus auf. Sie müssen alle eine Probe auf KRAFT ablegen, und wer scheitert, erleidet einen körperlichen oder geistigen Zustand nach eigener Wahl. Das Feuer unten ist ausgegangen, und Axel Trygg müht sich, es wieder zu entfachen."},
  {n:"Seltsame Unfälle", x:"Im Gasthaus geschehen weiter seltsame Unfälle. Zum Beispiel:<br>– Eine Spielerfigur stolpert und stürzt die Treppe hinunter. Die Figur muss eine Probe auf BEWEGLICHKEIT ablegen – bei einem Misserfolg erleidet sie einen körperlichen Zustand.<br>– Die Pferde brechen aus dem Stall aus und rennen in den Schnee. Eine Spielerfigur kann mit einer gelungenen Probe auf BEWEGLICHKEIT helfen, eines einzufangen. Nach jedem Versuch muss die Spielerfigur eine Probe auf KRAFT ablegen, um der Kälte zu widerstehen (S. 72).<br>– Eine Öllampe stürzt zu Boden und setzt den Boden in Brand. Eine Spielerfigur in der Nähe kann das Feuer mit einer gelungenen Probe auf BEWEGLICHKEIT löschen. Es sind drei Versuche möglich, bevor das Gebäude in Flammen steht."},
  {n:"Ilya verschwindet", x:"Axel Trygg oder ein anderer Nichtspielercharakter weist darauf hin, dass Ilya schon lange fort ist, mindestens eine Stunde. Er wollte nach den Pferden sehen. Axel bittet die Gäste, bei der Suche nach dem Kutscher zu helfen. Eine Spielerfigur oder ein passender Nichtspielercharakter findet ihn bald in einer Schneewehe nahe dem Teich, die Lippen blau vor Unterkühlung. Ilya hat sich die ganze Kleidung ausgezogen. Er scheint gefallen oder über etwas gestolpert zu sein und sich den Kopf aufgeschlagen zu haben. Es ergibt keinen Sinn, dass er sich bei dieser Kälte so nahe am Gasthaus verirrt haben sollte. „Etwas muss ihn gelockt haben“, murmelt Axel. Ilyas Leben ist nicht mehr zu retten, aber eine Spielerfigur, die eine Probe auf HEILKUNDE besteht, kann ihn lange genug am Leben halten, dass er murmeln kann, die Kälte habe zu ihm gesprochen."},
  {n:"Revenant-Verdacht", x:"Die Brüder Campbell vermuten, dass ein Wiedergänger die Unfälle verursacht. Sie behaupten, eine graue Gestalt durch das Haus huschen gesehen zu haben, und haben plötzliche Kälteschauer gespürt. Die Brüder werten dies als weiteren Beweis dafür, dass sie es mit einem ruhelosen Geist zu tun haben. Erfahren sie, dass der Kutscher Ester einen Heiratsantrag gemacht hat (aus dem Brief in Esters Zimmer), werden die Brüder Campbell überzeugt sein, dass der fragliche Wiedergänger in Wirklichkeit Esters Geist ist, der Schwester des Gastwirts, und dass sie hinter Ilyas Unfall steckt. Die Brüder wollen wissen, wo Ester begraben liegt."},
  {n:"Feuer erlöschen", x:"Die Feuer im Gasthaus und in der Sauna gehen ohne erkennbaren Grund immer wieder aus, und das Gebäude wird kälter. Wer sich nach draußen wagt, riskiert zu erfrieren – die Spielercharaktere müssen häufige Proben auf KRAFT ablegen, um der Kälte zu widerstehen, wie auf S. 72 beschrieben."},
  {n:"Feuerholz-Streit", x:"Axel Trygg oder ein anderer geeigneter Nichtspielercharakter schlägt vor, die Kutsche der Campbells als Brennholz zu verwenden. Die Brüder protestieren heftig, und es kann zu einem Handgemenge kommen. Die Spielercharaktere können zwischen ihnen vermitteln oder sich auf eine der beiden Seiten schlagen."},
  {n:"Kälte im Haus", x:"Es wird im Gasthaus so kalt, dass auch drinnen regelmäßig Proben auf KRAFT (S. 72) abgelegt werden müssen, um zu überleben. Die Straßen sind weiterhin eingeschneit."},
  {n:"Katastrophe", kat:1, x:"Die Brüder Campbell überzeugen Axel schließlich, dass der Wiedergänger seiner verstorbenen Schwester hinter allem steckt und dass ihre Überreste gesalzen und verbrannt werden müssen, damit sie Frieden findet. Während sie den Plan ausführen, ist Graufuß empört darüber, dass Ester so geschändet wird, und zwischen dem Nisse und den Brüdern bricht ein Kampf aus. Werden sie nicht aufgehalten, töten die Campbells Graufuß. Die Verzweiflung wächst. Der Winter wird der kälteste seit Menschengedenken. Als der Frühling kommt, werden Axel Trygg, die Bediensteten und die Gäste des Gasthauses erfroren aufgefunden. Unter den Einheimischen heißt es, Väterchen Frost habe seinen Tribut gefordert. Sind die Spielercharaktere noch im Gasthaus, wenn das geschieht, haben sie die Chance, durch eine dramatische Flucht in den Wald zu überleben. Nach einigen Proben auf KRAFT, um der Kälte zu widerstehen, trifft ein Schlitten vom Gut des Grafen Konstantinowitsch ein. Der Graf hat nach den vermissten Gästen schicken lassen, und der Bote kommt gerade noch rechtzeitig."}
 ],
 kaelte: {t:"Der Kälte widerstehen", p:72, x:"Eine Spielerfigur, die schwerer Kälte ausgesetzt ist, muss in regelmäßigen Abständen Proben auf KRAFT ablegen. Es funktioniert wie eine Furchtprobe gegen Furcht 1 (S. 68 im Grundregelwerk), nur dass die Probe mit KRAFT gewürfelt wird und ein Misserfolg zusätzlich zur normalen Wirkung (ein geistiger Zustand und vorübergehender Kontrollverlust) einen körperlichen Zustand zur Folge hat. Wer von der Kälte Gebrochen wird, muss weiter Proben auf KRAFT ablegen und erfriert beim nächsten Misserfolg. Die Wirkung der Kälte hält an, bis das Opfer wieder in die Wärme gelangt."},

 orteIntro: "Die folgenden Absätze fassen die wichtigsten Orte im und um das Gasthaus zusammen, die die Spielercharaktere untersuchen können. Das Gasthaus Tammsalu ist ein großes Stelzenhaus mit Strohdach. Neben dem Hauptgebäude steht ein Stall für Pferde und Vieh, und unter einer großen Eiche an einem kleinen – nun zugefrorenen – Teich liegt eine separate Sauna. An einer Seite des Gasthauses liegt ein kleiner Garten, in dem im Sommer Beeren und Gemüse angebaut werden, und in einer Ecke des Gartens befinden sich die Familiengrabstätte und eine kleine Kapelle. Solange der Schneesturm nicht nachlässt, ist es äußerst gefährlich, das Gasthaus zu verlassen. Charaktere, die nach draußen gehen, müssen regelmäßig Proben auf KRAFT bestehen (siehe den Kasten auf S. 72), um der Kälte zu widerstehen.",
 orte: [
  {id:"speisesaal", t:"Der Speisesaal", p:79, karte:"winter_karte_gasthaus", hier:["axel","vilma","samuel","daniel","karin"],
   text:["Der Speisesaal im Erdgeschoss des Gasthauses ist geräumig und offen und hat einen gemauerten Ofen mit Kamin. Vor dem Kamin liegt ein riesiges Bärenfell, und in der Nähe sind eine Anzahl Stühle und Tische aufgestellt. Der Raum ist warm und riecht köstlich nach Essen und Bier. Oft sitzen Gäste an den Tischen und essen, was Krööt und Imre servieren. Eine offene Holztreppe führt in das zweite Stockwerk, wo die Zimmer der Familie und die Gästezimmer liegen."],
   herausf:["Im Folgenden einige Ereignisse und Herausforderungen, die am ersten Abend der Spielercharaktere im Gasthaus im Speisesaal auftreten können:",
            "· Eine langhaarige graue Katze läuft einer der Spielerfiguren direkt vor die Füße. Die Figur stolpert und muss eine Probe auf BEWEGLICHKEIT bestehen, um nicht zu fallen und sich zu verletzen (körperlicher Zustand).",
            "· Spät am Abend versammeln sich die Gäste am Kamin, um Geschichten zu erzählen. Axel Trygg sagt, dies sei Tradition im Gasthaus, und lädt die Spielercharaktere ein mitzumachen – sie können Geschichten über vergangene Mysterien erzählen oder etwas ganz anderes, wahr oder erfunden. Jede teilnehmende Spielerfigur legt eine Probe auf INSPIRATION ab – bei Erfolg heilt eine andere Spielerfigur einen geistigen Zustand. Die Geschichten der anderen Gäste stehen unten in den Kästen der Erzählrunde. Rat zur Gestaltung der Erzählrunde in deinem Spiel steht im Kasten auf S. 81."],
   hinwText:"Im Speisesaal gibt es viele Informationen zu sammeln, vor allem im Gespräch mit Axel Trygg und den anderen Gästen des Gasthauses. In der Regel braucht es eine gelungene Probe auf MANIPULATION, damit ein Nichtspielercharakter sich öffnet, außer an Erzählabenden (siehe oben).",
   hinw:[
    {id:"s1", x:"Axel kann ihnen mehr über die Geschichte seiner Familie und des Gasthauses erzählen (siehe Hintergrund auf S. 69)."},
    {id:"s2", x:"Auf dem Kaminsims steht ein gemaltes Porträt einer hellhaarigen Frau mittleren Alters mit grünen Augen und kunstvoll geflochtenen Zöpfen. Auf Nachfrage erklärt Axel, dass die Frau seine Schwester Ester ist, die vor einigen Monaten verstarb. „Sie war eine Träumerin, eine sensible Seele, und seit sie ein Kind war, sprach sie oft mit unsichtbaren Freunden. Nun kann mir nichts meine Schwester zurückbringen.“ Axel kann ihnen auch erzählen, dass Ester im vergangenen Frühling tot im Teich gefunden wurde (siehe Hintergrund auf S. 69)."},
    {id:"s3", x:"Fragen die Spielercharaktere nach ihrer Frisur, antwortet Axel: „Ester wachte oft mit den schönsten Zöpfen im Haar auf. Ich verstehe bis heute nicht, wie das geschah.“ Die Erinnerung treibt ihm eine Träne ins Auge."},
    {id:"s4", x:"Die Erzählungen der Nichtspielercharaktere enthalten Hinweise, die zur Lösung des Mysteriums hilfreich sein können – Axel erzählt die Geschichte des Hofes, Frau Karaskeva singt von Domovoi, und Ilya erzählt die Geschichte von Väterchen Frost. Andere Geschichten können falsche Spuren enthalten – Frau af Zimt spricht von ruhelosen Geistern und verstorbenen Verwandten, die die Wahrheit über ihren Tod enthüllen. Die Brüder Campbell erzählen die Geschichte der Weißen Frau, eines Wiedergängers, der den eigenen Tod rächt, indem er Unfälle herbeiführt."},
    {id:"s5", x:"Fragen die Spielercharaktere Frau Karaskeva, erklärt sie, dass ihr Runenlied von den Domovoi des Hofes handelte – einem Vaesen, das Heim und Herd der Menschen schützt, das die Charaktere aber als Nisse erkennen. Domovoi sind mächtige Wesen, die ihren Herd beschützen und manchmal Glück bringen können, aber auch Ärger verursachen, wenn sie schlecht behandelt werden – weshalb es Brauch ist, ihnen Essen hinzustellen. In Russland glaubt man, dass Domovoi im Herd des Hauses oder in der Sauna leben und den Haushalt beschützen, wenn sie gut gepflegt werden. Zieht die Familie in ein anderes Haus um, ziehen die Domovoi in einem kleinen Birkenrindenschuh mit."},
    {id:"s6", x:"Würfeln die Spieler eine Probe auf MANIPULATION, kann Frau Karaskeva mehr Informationen über die Domovoi/Nisse geben. Gib für jeden gewürfelten Erfolg eine Information: Der beste Weg, einen verschmähten Nisse zu besänftigen, ist, ihm Brei, Brot oder Milch und ein wenig Aufmerksamkeit zu geben. – Nisse lassen sich mit Spinnenseide binden. Das raubt ihnen ihre Kraft und verhindert, dass sie sich befreien. – Ein Nisse lässt sich mit einem Nagel aus einem verfallenen Bauernhaus töten. Der Nagel muss dem Nisse durchs Herz getrieben werden."}
   ],
   geschichten:[
    {n:"Vilma af Zimts Geschichte", img:"som/winter_vilma", x:"„Seit ich elf Jahre alt war, kann ich mit Geistern kommunizieren. Vor anderthalb Jahren war ich im Haus meiner Familie in Sigtuna, um an der Beerdigung meiner Nichte Alva teilzunehmen. Sie war auf dem Heimweg von der Schule verschwunden. Die Polizei und Freiwillige organisierten eine Suche in den Wäldern zwischen der Schule und unserem Familienhaus, aber Alva konnte nicht gefunden werden. Meine Schwester war untröstlich und erzählte mir, dass sie seit Alvas Verschwinden ein seltsames Klopfen im Haus gehört habe und dass Gegenstände plötzlich umgefallen oder vertauscht worden seien. Auf Rat unseres Pfarrers veranstaltete die Familie schließlich eine Beerdigung mit leerem Sarg, um das Andenken des Mädchens zu ehren. In der Nacht nach der Beerdigung wachte ich frierend in meinem Zimmer auf, und als ich aufblickte, glaubte ich, in einem Spiegel Alvas Gesicht zu sehen. Als ich das Licht anmachen wollte, fiel plötzlich ein Buch aus dem Regal. Auf der aufgeschlagenen Seite war ein Bild eines verlassenen alten Häuschens im Wald. Am Morgen ging ich dorthin. Das Haus war leer, und in den verfallenen Räumen war nichts als alter Plunder. Ich wollte gerade zurückgehen, als ich plötzlich Alva am alten Brunnen stehen sah. Ich ging hin. Der morsche Brunnendeckel war zerbrochen. ‚Hilf mir, Tante‘, sagte eine Stimme aus der Dunkelheit. Ich rannte um Hilfe und kehrte mit meinen Verwandten zurück. Die Überreste eines Mädchens wurden aus der Schwärze des Brunnens gehoben. Es war unsere Alva, die mir den Weg zu ihrem leblosen Körper gezeigt hatte. Ich konnte sie nicht retten, aber ich konnte ihr Frieden geben.“"},
    {n:"Ilyas Geschichte", img:"som/winter_ilya", x:"„Hier im Wald sind wir alle der Grausamkeit der Natur ausgesetzt, die ihr erlebt habt. Die Kälte hat hier einen Namen – Morozko, oder Väterchen Frost. In einem der Nachbardörfer lebte einst eine Frau, die eine Tochter hatte, die sie vergötterte, und eine Stieftochter, die sie hasste. Eines Tages sagte die Frau zu ihrem Mann, er solle die Stieftochter hinaus auf die Winterfelder bringen und dort zum Sterben zurücklassen. Von Liebe geblendet gehorchte er. Morozko fand sie dort. Sie war höflich und freundlich zu ihm, also schenkte er ihr eine Truhe voll schöner Dinge und feiner Gewänder. Ein paar Tage später schickte die Stiefmutter den Vater, den Leichnam des Mädchens zur Beerdigung zu holen. Er fand sie lebendig an einem Baum, umgeben von kostbaren Gaben. Als die Stiefmutter sah, was das Mädchen mitgebracht hatte, sagte sie ihrem Mann, er solle auch ihre eigene Tochter in die winterliche Kälte hinaus bringen. Anders als ihre Stiefschwester war dieses Kind unhöflich zu Morozko, und so ließ er sie erfrieren. Als ihr Körper gefunden wurde, bereute die Mutter bitter, was sie getan hatte und dass sie ihrer Tochter keine Freundlichkeit beigebracht hatte. Ester sagte immer, menschliche Freundlichkeit sei das Einzige, was die Kälte abwehren kann.“"},
    {n:"Die Geschichte der Brüder Campbell", img:"som/winter_samuel_campbell", x:"„Wir haben kürzlich mehrere rätselhafte Todesfälle zwischen Jamburg und Narva untersucht. Mehrere Menschen waren bei seltsamen Unfällen ums Leben gekommen, bei denen ihre Kutschen von der Straße abgekommen waren. Ein armer Teufel überlebte lange genug, um uns zu erzählen, dass er kurz vor dem Verlust der Kontrolle über die Pferde eine Frau in Weiß auf der Straße gesehen hatte. Weiße Frauen gibt es in vielen Formen. Meist sind sie der Wiedergänger einer Frau, die verraten und ermordet wurde oder wegen unerwiderter Liebe durch eigene Hand eines gewaltsamen Todes starb. Im Gespräch mit den Einheimischen erkannten wir, dass es der Wiedergänger einer Frau sein könnte, die auf dem Heimweg von ihrer Hochzeit von ihrem eigenen Bräutigam ermordet wurde. Seither spukt sie auf den Straßen rund um das Dorf, wahnsinnig vor Trauer und Rache. Wir durchsuchten die Wälder und fanden ihren Leichnam auf einer Lichtung. Sie trug noch ihr Hochzeitskleid, der Kopf in unnatürlichem Winkel geneigt. Plötzlich sahen wir sie vor uns. Ruhelose Geister sind gewalttätig, und sie schleuderte Daniel mit solcher Wucht gegen einen Baum, dass er bewusstlos wurde. Das war das letzte Mal, dass sie ihre Rache übte, und ihr Geist zerfiel vor unseren Augen zu Staub.“"},
    {n:"Karin Karaskevas Lied", img:"som/winter_karin", x:"Axel geht zu der alten Frau, die dem Feuer am nächsten sitzt. „Es ist eine Ehre, Sie hier zu haben, Frau Karaskeva.“ Er wendet sich an die anderen Gäste. „Karin Karaskeva ist eine Runensängerin mit tiefem Wissen über die örtliche Volkskunde und die Vaesen. Sie hat ein bemerkenswertes Gedächtnis und kennt Tausende von Runen – oder Liedern – aus der Gegend sowie Hunderte alter Sprichwörter. Würden Sie unseren Abend mit etwas aus Ihrem reichen Repertoire bereichern?“ Frau Karaskeva blickt auf, und einen Moment lang wirkt der Raum etwas wärmer, und das sterbende Feuer lodert wieder auf. Nachdem sie ihr Lied beendet hat, erklärt sie in gebrochenem Schwedisch, dass es von einem Domovoi handelte, dem das neue Pferd des Haushalts nicht gefiel. Eines Morgens fand der Bauer das Pferd schweißnass in seinem Stall. Der Nisse hatte die Gestalt eines Wiesels angenommen und das Pferd geritten und gekitzelt, bis es völlig erschöpft war. Schließlich kaufte der Bauer einige Glocken und band sie dem Pferd um den Hals, was den Nisse dazu brachte, ihn in Ruhe zu lassen. Als die Runensängerin zu Ende erzählt hat, legt sie ein Stück Brot und einen Schuss Bier auf den Kaminsims. Axel lacht und sagt sanft, dass seine Mutter und seine Großmutter das auch getan haben. „Sie waren wirklich abergläubisch.“"}
   ],
   kasten:[
    {t:"NSC im Gasthaus", p:77, x:"<b>Axel Trygg:</b> Gastwirt (S. 77).<br><b>Die Witwe Riina Soovere:</b> Köchin im Gasthaus. Braunes Haar mit grauen Strähnen unter einer Haube. Warm und herzlich. Ihre flinken Hände kochen köstliches Essen.<br><b>Ilya Jermakow:</b> Kutscher (S. 73).<br><b>Imre Soovere:</b> Sohn von Riina, Knecht und Kellner. Klein, mit kurzem, lockigem braunem Haar und charmanten braunen Augen. Imre ist gesprächig und spielt nach dem Abendessen gern Karten mit den Gästen.<br><b>Krööt Soovere:</b> Tochter von Riina und Kellnerin. Lockiges braunes Haar zu einem unordentlichen Knoten gebunden, dünn, schreckhaft, mit prüfenden Augen. Liebt Märchen.<br><b>Vilma af Zimt:</b> Gast, Künstlerin, Medium (S. 74).<br><b>Samuel und Daniel Campbell:</b> Gäste, Brüder, Geisterjäger (S. 78).<br><b>Karin Karaskeva:</b> Gast, Runensängerin (S. 79)."},
    {t:"Die Erzählrunde spielen", p:81, x:"Das Erzählen von Geschichten im Speisesaal lässt sich je nach den Vorlieben deiner Spielgruppe auf unterschiedliche Weise ausspielen. Wollen die Spieler Geschichten erzählen, ist das eine gute Gelegenheit, sie ihre Charaktere entwickeln und beschreiben zu lassen, etwa indem sie das Trauma ihrer ersten Begegnung mit einem Vaesen beschreiben (S. 18 im Grundregelwerk). Diese Geschichten können von den Spielern erzählt oder mit einer Probe auf INSPIRATION kurz abgehandelt werden. Die Spielercharaktere können auch ablehnen, Geschichten zu erzählen, und nur den Nichtspielercharakteren zuhören. Die Geschichten der Nichtspielercharaktere kannst du als Spielleiter vorlesen, oder du bittest die Spieler zur Abwechslung, sie vorzulesen."},
    {t:"Runensänger", p:83, x:"Ein Runensänger ist eine Art lebendes Geschichtenbuch, durch das traditionelle Lieder, Sprichwörter und Erzählungen bewahrt werden. Die Lieder sind in einem besonderen Versmaß geschrieben, dem Runenmaß, das ihnen einen bestimmten Rhythmus verleiht und durch Wiederholungen und Alliterationen den Runensängern hilft, sich die langen Gedichte und Lieder zu merken. Runensänger gab es zur Zeit dieses Abenteuers in mehreren Ländern, und sie waren besonders wichtig für unverschriftlichte Sprachen wie Wotisch und Ingrisch. Runensänger reisten oft in verschiedene Dörfer und traten bei Familienfeiern und Festen auf."}
   ]},
  {id:"ester", t:"Esters Zimmer", p:83, karte:"winter_karte_gasthaus", hier:[],
   text:["Obwohl Monate seit ihrem Tod vergangen sind, ist Esters Zimmer noch immer leer. Es wurde gereinigt und riecht angenehm nach frischer Fichte. In dem Zimmer stehen ein Kleiderschrank, ein großes Bett mit einem kunstvoll gearbeiteten Kopfteil aus Kiefernholz, und am kleinen Fenster ein Stuhl und ein kleiner Tisch voller Bücher."],
   herausf:["Esters Zimmertür ist verschlossen, aber die Spielercharaktere können Axel bitten, nachzusehen, oder den Schlüssel stehlen, der im Schlüsselschrank des Gasthauses an einem Haken hängt. Sie können das Schloss auch mit HEIMLICHKEIT knacken oder die Tür mit KRAFT eintreten (obwohl Axel dann schnell auf der Bildfläche erscheint und alles andere als erfreut sein wird, wenn jemand Letzteres versucht)."],
   hinwText:"",
   hinw:[{id:"e1", x:"Die Spielercharaktere finden auf dem Tisch ein ledergebundenes Buch. Es ist Esters Tagebuch, und es enthält viele Gedanken zu großen und kleinen Themen und zum Alltag auf dem Hof. Doch ein bestimmter Eintrag vom letzten Sommer fesselt das Interesse der Spielercharaktere – siehe Handout 4B."}],
   kasten:[{t:"Esters Tagebuch (Handout 4B)", p:83, x:"<b>17. Juni.</b> Vor zwei Wochen hat Ilya mir einen Heiratsantrag gemacht. Mir blieb nichts anderes übrig, als ihn abzuweisen. Er wollte mich aus dem Gasthaus fort in ein Leben in Sankt Petersburg mitnehmen. Er versteht es nicht. Ich habe kalt geantwortet, obwohl es mir das Herz brach. Ilya hatte mir einen wunderschönen silbernen Kamm gekauft. Er muss ein Vermögen gekostet haben. Ich sagte, ich habe bereits einen anderen Freund. In gewisser Weise habe ich das, schon immer. Und Axel braucht mich hier. Das Gasthaus bedeutet mir alles, und ich will alles in meiner Macht Stehende tun, unser Erbe zu bewahren. Ilyas Miene verfinsterte sich wie ein Gewitter über dem Wald im Sommer, und er verließ den Hof. Er ist nicht zurückgekehrt. Nachts, wenn es still im Haus wird, frage ich mich, ob ich die richtige Wahl getroffen habe."}]},
  {id:"zimmer", t:"Axels Zimmer und Gästezimmer", p:84, karte:"winter_karte_gasthaus", hier:["axel"],
   text:["<b>Axel Trygg</b>: Gegenüber der Tür liegt eine tiefe Fensternische mit Blick auf den Teich und die große Eiche. Das Zimmer ist schlicht eingerichtet – ein Bett mit geschnitztem Kopfteil, ein Nachttisch mit einer Bibel, ein Kleiderschrank und ein in der Art der Region gewebter Teppich mit bunten Runen im Muster. In einer Ecke steht ein Schreibtisch mit Büchern und Papier. Ein alter Birkenrindenschuh hängt eingerahmt und verglast an der Wand.",
          "<b>Gästezimmer</b>: Das Gasthaus hat sieben Gästezimmer, alle mit einfachen, aber gut gearbeiteten Möbeln eingerichtet. Jedes Zimmer hat zwei Betten und einen Nachttisch. Die Brüder Campbell wohnen in Zimmer 1, Ilya in Zimmer 2, Vilma af Zimt in Zimmer 4 und Karin Karaskeva in Zimmer 7. Die übrigen Zimmer stehen den Spielercharakteren zur Verfügung."],
   herausf:[],
   hinwText:"",
   hinw:[
    {id:"z1", x:"Auf dem Schreibtisch liegen Finanzunterlagen, Bücher über Kartenspiele und Pläne für den neuen Stall mit mehr Platz für Kutschen."},
    {id:"z2", x:"Der Birkenrindenschuh ist der, den seine Familie zusammen mit Graufuß aus Schweden mitgebracht hat. Er ist ein Hinweis darauf, dass es im Gasthaus einen Nisse gibt."}
   ]},
  {id:"stall", t:"Der Stall", p:84, karte:"winter_karte_tammsalu", hier:["ilya"],
   text:["Der Stall ist alt, aber gut gepflegt. Drinnen ist es warm und riecht nach Heu und Mist. An den Wänden reihen sich Boxen, in denen die Pferde der Familie Trygg stehen, zusammen mit denen der Postkutsche. Darüber liegen Balken und ein Heuboden. Ilya verbringt viel Zeit damit, im Stall die Pferde zu versorgen."],
   herausf:["Als die Spielercharaktere den Stall betreten, fällt plötzlich ein schwerer Eimer von einem der Balken an der Decke. Eine zufällige Spielerfigur muss eine Probe auf BEWEGLICHKEIT bestehen, um aus dem Weg zu springen und nicht getroffen zu werden (körperlicher Zustand). Auf Nachfrage ist Ilya überrascht – er ist sicher, dass er ihn gerade eben auf den Boden gestellt hatte."],
   hinwText:"",
   hinw:[
    {id:"st1", x:"Wollen die Spielercharaktere mit Ilya sprechen, finden sie ihn höchstwahrscheinlich hier. Nachdem er erfolgreich MANIPULIERT wurde, kann er ihnen von seiner unerwiderten Liebe zu Ester erzählen (siehe die Charakterbeschreibung auf S. 73)."},
    {id:"st2", x:"Eines der Kutschpferde wurde bei dem Unfall verletzt. Eine Spielerfigur, die das Pferd untersucht, sieht, dass sein Bein sauber umwickelt und verbunden wurde. Die Mähne des Pferdes ist zu kunstvollen Zöpfen geflochten, die, soweit die Spielerfigur sich erinnert, vorher nicht da waren."},
    {id:"st3", x:"Eine Spielerfigur kann eine kleine graue Gestalt hinter der Ecke der Sauna verschwinden sehen. Charaktere, die versuchen, ihr zu folgen, finden keine Spur von ihr."}
   ],
   kasten:[{t:"Der Nisse Graufuß", p:84, x:"Der Nisse Graufuß folgt den Tryggs seit Generationen und zog mit ihnen vom Familienhof bei Falun nach Ingermanland. Graufuß hat einen intensiven Blick in seinen bernsteinfarbenen Augen und erscheint als kleiner alter Mann in grober Arbeitskleidung und grauem Hut mit langem, geflochtenem Bart. Er spricht eine alte Form des Schwedischen sowie mehrere andere Sprachen, die er im Lauf der Jahre aufgeschnappt hat. Er spricht knapp und wirkt mürrisch, aber sein Herz sitzt am rechten Fleck. Der Nisse hat ein wechselhaftes Verhältnis zur Familie auf dem Hof. Solange sie ihn bei Laune halten, benimmt er sich gut und ist dem Haushalt treu. Graufuß liebte Ester, die seit ihrer Kindheit mit ihm gesprochen und immer etwas Brot, Milch oder Brei am Ofen hingestellt hatte. Es hatte ihn tief erschüttert, Ester am Teich zusammenbrechen zu sehen, doch er wusste, dass ihr Leben nicht mehr zu retten war. Wie Axel hat er auf seine Weise um sie getrauert, und ein Teil des Ärgers, den er verursacht, ist seine Art, seine Gefühle auszuleben. Axels Vernachlässigung und die Tatsache, dass er Kartenspiele im Gasthaus zulässt, haben den Nisse wütend und rachsüchtig gemacht. Graufuß kann sich in eine langhaarige Katze verwandeln und tut dies, um sich unter den Gästen des Gasthauses zu bewegen. Gelegentlich wirft die Katze jemandes Bierkrug um oder stiehlt den Platz einer Spielerfigur, wenn sie zum Abort geht. Eine Spielerfigur kann auch in ihrem Zimmer eine Anwesenheit spüren und plötzlich bemerken, wie die Katze sie verächtlich anstarrt. Graufuß hat die Werte und Eigenschaften eines gewöhnlichen Nisse (siehe S. 148 im Grundregelwerk)."}]},
  {id:"kutsche", t:"Die Postkutsche", p:85, karte:"winter_karte_tammsalu", hier:["vilma"],
   text:["Etwa eine Wegstunde vom Gasthaus entfernt liegt die Postkutsche, in der die Spielercharaktere angekommen sind. Sie können hierher zurückkehren, um Vilma af Zimts Tarotkarten zu holen (siehe den Kasten Die Tarot-Legung) oder ihre eigenen verlorenen Habseligkeiten zu bergen. Wenn die Charaktere zur Kutsche zurückkehren, finden sie sie von einer dicken Schneeschicht bedeckt und von riesigen, schneebeladenen Fichten umgeben. Der Ort wirkt nun friedlich. Die Postkutsche liegt auf der Seite, die Habseligkeiten der Gruppe verstreut im Schnee rundherum."],
   herausf:["Die Charaktere können an der Postkutsche mehreren Herausforderungen begegnen.",
            "· Auf dem Weg zur Kutsche und zurück muss jede Spielerfigur eine Probe auf KRAFT bestehen, um der Kälte zu widerstehen (S. 72). Nach jedem Versuch, Gegenstände im Schnee zu finden, außer nach dem ersten, muss eine weitere Probe abgelegt werden. Das ist ein guter Zeitpunkt für eine der Figuren, eine Vision von Väterchen Frost zu haben (S. 74).",
            "· Die Spielercharaktere müssen eine Probe auf UNTERSUCHUNG bestehen, um Vilma af Zimts Tarotkarten oder einen anderen im Schnee verlorenen Gegenstand zu finden. Mehrere Versuche sind erlaubt, aber nach jedem Versuch (außer dem ersten) muss die Figur eine weitere Probe auf KRAFT ablegen, um die Kälte zu ertragen."],
   hinwText:"Die Spielercharaktere können bei ihrem Besuch an der Postkutsche mehrere Hinweise erlangen:",
   hinw:[
    {id:"k1", x:"Auf dem Kutschbock liegt ein Porträt von Ester Trygg. Es gehörte Ilya, was er auf Nachfrage zugibt."},
    {id:"k2", x:"Eine Spielerfigur, die innehält und in den Wald blickt, kann eine Gestalt in Weiß sehen, die sich lautlos über den Schnee bewegt. Versucht die Figur, ihr zu folgen, verschwindet die Gestalt spurlos."}
   ],
   kasten:[
    {t:"Die Tarot-Legung", p:85, x:"Zu einem passenden Zeitpunkt bei den Ermittlungen der Spielercharaktere wird die Esoterikerin Vilma af Zimt (S. 74) Wahrsagekarten, bekannt als Tarot, verwenden, um festzustellen, ob es im Gasthaus einen Wiedergänger gibt. Aber sie braucht jemanden, der ihr Tarotspiel holt, das sie nach dem Unfall in der Postkutsche zurückgelassen hat. Sie bittet die Spielercharaktere, es zu holen (möglicherweise zusammen mit dem Kutscher Ilya, wenn er noch lebt). Näheres siehe Die Postkutsche.<br><br>Hat sie ihre Karten zurück, kann Vilma damit herausfinden, was im Haus vor sich geht. Sie legt ihre seltsamen handbemalten Karten auf den Tisch im Speisesaal. Jeder ist willkommen, sich ihr anzuschließen. Ihre Finger gleiten über die seltsamen Karten, die sie fächerförmig ausbreitet. Langsam deckt sie drei Karten auf, eine nach der anderen. Sie wirft der Gruppe einen langen, neugierigen Blick zu und erklärt, dass die Karten verschiedene Aspekte der Lage widerspiegeln, aber keine eindeutige Wahrheit liefern.<br><br>„Die Karten sind nur ein Werkzeug bei unserer Suche und erfordern Deutung. Sie können für verschiedene Menschen Verschiedenes bedeuten. Heute scheinen sie mehr Fragen aufzuwerfen, als sie beantworten.“<br><br>Drei Karten liegen auf dem Tisch – siehe Handout 4C. Die Spielercharaktere können eine Probe auf WISSEN ablegen, um die folgenden Informationen darüber zu erhalten, wie diese Karten gedeutet werden können:<br><b>Der Stern:</b> Hoffnung, Offenheit, das Unbewusste, eine Flut von Gefühlen, Venus.<br><b>Drei der Schwerter:</b> Kummer, Herzschmerz, Schmerz.<br><b>Der Eremit:</b> Eine Suche nach Wahrheit, Rückzug von anderen, Einsamkeit."}
   ]},
  {id:"sauna", t:"Die Sauna", p:86, karte:"winter_karte_tammsalu", hier:[],
   text:["Die Sauna liegt am zugefrorenen Teich hinter dem Gasthaus, unter den ausladenden Ästen der Eiche. Die Leute kommen hierher, um Wasser zu erhitzen und sich zu waschen. Mitten im Vorraum brennt in einer offenen Feuerstelle ein Feuer. Rund um das Feuer stehen Holzbänke, und an den Wänden hängen Eisenhaken zum Aufhängen der Kleider. Holzeimer lassen sich mit Wasser füllen und zum Erhitzen in die Sauna stellen. Es gibt auch Bündel von Birkenzweigen, mit denen man sich sanft peitschen kann. Eine große langhaarige Katze liegt ausgestreckt auf einem Fell am Herd und seinem knisternden Feuer.",
          "Dies ist eine Rauchsauna. Wenn sie angeheizt werden soll, wird ein Fenster geöffnet und unter den Saunasteinen ein Feuer entzündet. Der Rauch zieht dann aus dem Fenster, das an den Rändern geschwärzt ist. Sobald das Brennholz heruntergebrannt und die Steine heiß sind, wird das Fenster geschlossen, und das Saunabad kann beginnen. In der Sauna gibt es Stufenbänke zum Sitzen und einen Holzeimer mit einer Kelle, um Wasser auf die Steine zu gießen. Es riecht stark nach Rauch, doch die Luft ist mild und angenehm zu atmen."],
   herausf:[],
   hinwText:"",
   hinw:[
    {id:"sa1", x:"In einer Ecke der Sauna liegt ein silberner Kamm, teilweise unter dem Brennholz verborgen. Die Spielercharaktere können ihn finden, indem sie das Brennholz absuchen oder eine Probe auf UNTERSUCHUNG bestehen."},
    {id:"sa2", x:"In der Sauna stehen mehrere geschnitzte Holzfiguren von Tieren, mit kunstvollen Mustern verziert. Sie müssen von einem Meisterhandwerker geschnitzt und verziert worden sein."}
   ]}
 ],

 kf: {
  p: 86,
  einleitung:["Der Höhepunkt dieses Mysteriums kann sich auf viele verschiedene Arten abspielen. Finden die Spielercharaktere heraus, dass die Unfälle auf dem Hof wahrscheinlich von einem Nisse verursacht werden, sollten sie dem Nisse etwas zu essen hinstellen und seine Aufmerksamkeit auf sich ziehen. Graufuß zeigt sich den Charakteren dann. Wann genau das geschieht und wie schwer er zufriedenzustellen ist, sollte davon abhängen, wie schnell die Spieler zu diesem Schluss kommen. Können die Spielercharaktere es nicht selbst herausfinden, kann die Runensängerin Karin Karaskeva sie in die richtige Richtung stupsen.",
                "Ein Ort, an dem Graufuß sich wahrscheinlich zeigt, ist der Kamin des Gasthauses. Zuerst sehen die Spielercharaktere, wie die Katze von ihrem Platz am Ofen springt und hinter dem Kamin verschwindet. Der Herd gibt ein schwaches Glühen ab, das weder Licht noch Wärme spendet. Dann sehen die Charaktere ihn, zuerst als Schatten in der Ecke, dann erscheint ein kleiner alter Mann vor ihnen in hellgrauer Kleidung und gestrickter Mütze. Er richtet seinen Blick auf Axel, falls dieser anwesend ist. „So, du siehst mich endlich, Junge.“"],
  wege: [
   {t:"Den Nisse angreifen", x:[
    "Die Spielercharaktere können versuchen, den Nisse mit Spinnenseide zu binden, ihn mit Gewalt zu vertreiben oder sogar mit einem rostigen Nagel zu töten – das bringt aber Unheil über den Hof und endet wahrscheinlich damit, dass alle im Gasthaus erfrieren (siehe Katastrophe). Du kannst die Runensängerin Karin Karaskeva oder sogar Axel eingreifen lassen, wenn die Spielercharaktere beschließen, Gewalt gegen den Nisse anzuwenden."]},
   {t:"Den Nisse besänftigen", x:[
    "Die weiseste Lösung ist, mit dem Nisse zu sprechen und ihn zur Vernunft zu bringen. Nur so lässt sich Schutz vor der schrecklichen Kälte draußen gewinnen. Doch das Gespräch mit Graufuß ist ein Balanceakt – die Trauer um Esters Tod hat ihn mürrisch und leicht kränkbar gemacht (siehe die Charakterbeschreibung auf S. 84). Er kann den Spielercharakteren nun auch erzählen, wie Ester an einem Schlaganfall starb.",
    "Die Spielercharaktere und Axel müssen den Nisse davon überzeugen, dass er nicht länger ignoriert wird und dass er für den Hof wichtig ist. Der Nisse fürchtet, vergessen zu werden. Er will, dass Axel verspricht, ihm weiter Gaben darzubringen, und möglicherweise seine Pläne aufgibt, im Gasthaus Kartenspiele zu veranstalten. Spiele das Gespräch mit Graufuß aus und füge nach Belieben ein paar Proben auf MANIPULATION hinzu. Kein einzelner Misserfolg sollte jedoch die Versuche der Charaktere, den Nisse zur Vernunft zu bringen, zum Scheitern bringen, sondern die Dinge nur etwas erschweren."]},
   {t:"Die Geisterjäger", x:[
    "Zu einem passenden Zeitpunkt, bevor Graufuß sich von den Spielercharakteren besänftigen lässt, wird die Lage durch das Eingreifen der Brüder Campbell weiter verkompliziert. Das kann auf vielerlei Weise geschehen.",
    "Zunächst sind die Brüder überzeugt, dass Esters Geist die Unfälle in Gestalt eines Wiedergängers verursacht (siehe S. 150 im Grundregelwerk). Sie drängen Axel, ihnen zu zeigen, wo sie begraben liegt, damit sie ihre Überreste salzen und verbrennen können – eine Methode, die ihrer Behauptung nach Wiedergänger bannen kann. Zunächst weigert sich Axel, doch als mehr Unfälle geschehen und die Temperatur weiter sinkt, gibt er schließlich nach, und die Brüder setzen ihren Plan um, sofern die Spielercharaktere sie nicht aufhalten – siehe Katastrophe auf S. 75.",
    "Selbst wenn die Brüder (durch Gewalt oder Überzeugung) daran gehindert werden, Esters Überreste zu verbrennen, können sie bei der Konfrontation mit Graufuß dennoch Ärger machen. Sie haben ihre Hausaufgaben gemacht und wissen, dass Nisse mit einem rostigen Nagel durchs Herz getötet werden können. Sie greifen Graufuß an, wenn er erscheint, in dem Glauben, das Gasthaus zu retten. Sie begreifen nicht, dass der Schutz des Nisse das Einzige ist, was das Gasthaus vor der schrecklichen Kälte Väterchen Frosts retten kann.",
    "Die Brüder könnten auftauchen und Ärger machen, gerade wenn die Spielercharaktere auf dem Weg sind, Graufuß Vernunft einzureden. Samuel und Daniel versuchen, die Charaktere von ihrem Standpunkt zu überzeugen, schrecken aber nicht davor zurück, Gewalt anzuwenden, um ihren Willen durchzusetzen. Das kann zu einem Kampf führen, aber die Spielercharaktere können die Situation auch durch MANIPULATION der Brüder lösen – was nicht leicht wird, da sie einzeln behandelt werden müssen.",
    "Wird Esters Grab geschändet oder verletzen die Spielercharaktere oder die Brüder Campbell den Nisse, verlässt Graufuß das Gasthaus für immer und überlässt die Charaktere und die anderen ihrem Schicksal (siehe den Countdown)."]},
   {t:"Versöhnung", x:[
    "Ist die Bedrohung durch die Brüder Campbell abgewendet und gelingt es Axel und den Spielercharakteren, Graufuß zu besänftigen, leuchtet der Nisse auf und legt die Hand auf den Herdstein. „Ich glaube, wir verstehen uns endlich, Herr Axel.“ Der Nisse verblasst vor den Augen der Spielercharaktere, und sie spüren einen Puls – fast wie einen Herzschlag –, der von Graufuß ausgeht und sich durch die Gäste, den Raum, das Haus und den Garten ausbreitet. Das Feuer lodert auf, und eine wohlige Wärme erfüllt den Raum."]}
  ]
 },

 ns: {p: 87, t: "Nachspiel", x:["Überzeugen Axel und die Spielercharaktere Graufuß zu bleiben, erhält die Gruppe seinen Schutz, das Feuer im Gasthaus brennt wieder heiß, und Menschen und Tiere sind vor der gnadenlosen Kälte sicher. Der Schneesturm lässt nach, und draußen glitzert der Schnee in der Wintersonne. Im großen Saal des Gasthauses hört man das gemütliche Geräusch des Feuers, das seine angenehme Wärme im Raum verbreitet. Die Köchin Riina kocht Brei, und bevor sie ihn den Gästen serviert, stellt sie eine Schale Brei und einen Krug Milch an den Ofen.",
   "Ein Mann mit einem Schlitten trifft ein und überbringt eine Nachricht von Graf Konstantinowitsch. Das Konklave wurde verschoben. Die Spielercharaktere können nach Sankt Petersburg zurückkehren oder ihre Reise zu anderen Zielen fortsetzen."]},

 figOrder: ["axel", "ilya", "vilma", "samuel", "daniel", "karin"],
 figs: {
  axel: {n:"Axel Trygg", rolle:"Gastwirt", zitat:"„Das Gasthaus muss mit der Zeit gehen.“", p:77, img:"som/winter_axel_trygg",
   x:"Axel Trygg ist ein großer Mann mit breiten Schultern. Er redet und lächelt viel, aber in seinen Augen liegt Traurigkeit. Er träumt davon, das Gasthaus zu einem noch größeren Erfolg auszubauen und sein Angebot um Glücksspiel zu erweitern. Die örtliche Religionsgemeinschaft billigt das nicht, aber Axel ist überzeugt, dass Tammsalu mit Kartenspielen neue Höhen erreichen könnte. Er will die alten Ställe abreißen und einen größeren bauen, mit Platz für mehr Wagen. Doch Esters Tod hat ihn schwer getroffen, und diese Pläne ruhen derzeit. Axel ist stolz auf seine Familiengeschichte, glaubt aber nicht an die alten Geschichten über einen Nisse, und niemand stellt ihm mehr Gaben oder Essen hin.",
   a:[4,3,3,2], f:[["Kraft",3],["Beweglichkeit",2],["Fernkampf",2]], z:[2,2], ausr:"Messer, Jagdgewehr", hier:"Gasthaus Tammsalu"},
  ilya: {n:"Kutscher Ilya Jermakow", rolle:"Kutscher auf der Strecke Sankt Petersburg–Narva", zitat:"„Bleibt auf der Straße, niemand überlebt die Kälte im Wald.“", p:73, img:"som/winter_ilya",
   x:"Ilya ist ein hagerer Mann mit Stahl in den Augen. Er ist von durchschnittlicher Größe, mit dunkelbraunem Haar, einem dichten Schnurrbart und einem abgezehrten Gesicht. Er ist in dicke Tierfelle gehüllt, die er über seinem Wintermantel trägt, und in seinem Schnurrbart haben sich Eisperlen gebildet. Ilya fährt seine Postkutsche zwischen Sankt Petersburg und Narva und anderen Städten der Region.<br><br>Vor etwa einem Jahr hielt Ilya im Gasthaus Tammsalu um Esters Hand an, wurde aber abgewiesen. Er redet nicht gern darüber, gibt es aber zu, wenn man ihn drängt. Er ist ein Mann weniger Worte, erklärt aber, dass er in die Schwester des Gastwirts verliebt war und sie seit dem Frühling betrauert. Er wollte Ester heiraten und sich mit ihr in Sankt Petersburg niederlassen, doch Axel erhob Einspruch, da der Kutscher zu arm für seine Schwester sei. Ester war freundlich zu Ilya, doch seine Gefühle wurden nicht erwidert.<br><br>„In einer Frühlingsnacht schenkte ich Ester einen silbernen Kamm, den ich mit meinem sauer verdienten Geld bei einem Goldschmied in Sankt Petersburg gekauft hatte. Ester lächelte und sagte, sie brauche solchen Tand nicht, ihr Freund helfe ihr beim Flechten und Kämmen ihres Haares. Ich ließ ihr den Kamm. Ich konnte ihr Herz nicht gewinnen.“",
   a:[4,3,2,3], f:[["Beweglichkeit",3],["Fernkampf",1],["Nahkampf",2],["Wachsamkeit",2],["Beobachtung",2]], z:[2,2], ausr:"Gewehr, Messer", hier:"Stall · Gasthaus"},
  vilma: {n:"Frau Vilma af Zimt", rolle:"Künstlerin und Spiritistin aus Stockholm", zitat:"„Unsere Seelen sind durch göttliche Energie verbunden.“", p:74, img:"som/winter_vilma",
   x:"Vilma af Zimt ist Künstlerin und Spiritistin aus Stockholm. Sie hat hellbraunes Haar, das nach der Mode der Zeit zu einem schönen Knoten zurückgesteckt ist, wissbegierige, hellgrüne Augen und trägt die feinen Kleider einer Adligen. Vilma ist die Tochter des aufgeschlossenen Generals Peter af Zimt. Ihr Vater bezahlte ihr ein Malereistudium in Paris, wo sie für ihre abstrakten symbolistischen Gemälde bekannt geworden ist. Neben ihrer Kunst hat Vilma ein lebhaftes Interesse am Okkulten und Esoterischen entwickelt. Auf ihren Reisen durch Europa kam sie mit den Rosenkreuzern sowie den Begründern der Theosophie in Kontakt, mit denen sie einen regen Briefwechsel pflegt. Mit einer Persönlichkeit, so bunt wie ihre Kunst, hat sich Vilma in den Bohemekreisen Stockholms einen Namen gemacht, indem sie Lesekreise zu mystischen Texten, Séancen und Tarot-Legungen veranstaltet. Die Familie af Zimt ist eng mit Graf Konstantinowitsch befreundet, und wie die Spielercharaktere ist Vilma auf dem Weg zu seinem Gut, als der Sturm sie zwingt, im Gasthaus Tammsalu anzuhalten.",
   a:[2,3,4,4], f:[["Heimlichkeit",1],["Wachsamkeit",2],["Wissen",4],["Beobachtung",3],["Manipulation",3]], z:[4,2], ausr:"Skizzenbuch, Tarotkarten", hier:"Speisesaal"},
  samuel: {n:"Samuel Campbell", rolle:"Geisterjäger aus Winchester", zitat:"„Es gibt immer einen Weg nach vorn.“", p:78, img:"som/winter_samuel_campbell",
   x:"Die Brüder Campbell sind Ermittler übernatürlicher Aktivitäten aus Winchester in England. Daniel und Samuel reisen in einer schwarzen Kutsche umher, die von zwei schwarzen Pferden gezogen wird, und suchen Orte auf, an denen ungelöste Morde geschehen sind. Auch sie waren auf dem Weg zu Konstantinowitschs Gut, um am Konklave teilzunehmen, gerieten aber in den Sturm und checkten einige Stunden vor den Spielercharakteren im Gasthaus ein. Sie sind im Speisesaal zu finden, als die Charaktere ankommen.<br><br>Samuel ist groß und kräftig, mit schulterlangem dunkelbraunem Haar und freundlichen blauen Augen. Er hat ein Talent dafür, mit Menschen in Kontakt zu kommen. In seiner Jugend träumte Samuel davon, dem harten Leben auf der Straße zu entkommen und sich an der Universität Cambridge ausbilden zu lassen. Er führt eine große Sammlung von Büchern über paranormale Wesen und Phänomene mit sich und ist oft zu sehen, wie er seine Nase in diese Wälzer steckt.",
   a:[4,4,4,2], f:[["Kraft",2],["Nahkampf",3],["Fernkampf",4],["Wachsamkeit",3],["Beobachtung",2]], z:[2,3], ausr:"Gewehr", hier:"Gasthaus (Zimmer 1)"},
  daniel: {n:"Daniel Campbell", rolle:"Geisterjäger, der ältere Bruder", zitat:"„Meine Kutsche ist mein ganzer Stolz.“", p:78, img:"som/winter_daniel_campbell",
   x:"Daniel ist der ältere der Brüder. Er wurde von Kindheit an darin ausgebildet, Monster und Geister zu jagen. Er fühlt sich für seinen Bruder Samuel verantwortlich, auf den er seit ihrer Kindheit aufgepasst hat, da ihre Mutter früh starb und ihr Vater stets auf Reisen war. Daniel ist von durchschnittlicher Größe, hat hellbraunes Haar und mandelförmige braune Augen und ist kein Mann, den man leicht kennenlernt. Er hat einen Soldatenkörper mit Narben aus unzähligen Kämpfen. Er trägt einen knielangen Mantel und einen alten Revolver im Holster und führt ein ledergebundenes Buch mit sich, in dem er die Geschichten der Abenteuer der Brüder sammelt. Oft sitzt er allein trinkend herum, um die Erinnerungen an all die Schrecken zu betäuben, die er gesehen hat.",
   a:[5,3,2,4], f:[["Kraft",5],["Nahkampf",4],["Beweglichkeit",2],["Heimlichkeit",3],["Fernkampf",2],["Wachsamkeit",2]], z:[2,3], ausr:"Revolver, Kampfmesser mit seltsamen Symbolen", hier:"Gasthaus (Zimmer 1)"},
  karin: {n:"Karin Karaskeva", rolle:"Runensängerin", zitat:"„Die Lieder lehren uns über die vergessenen Völker.“", p:79, img:"som/winter_karin",
   x:"Die Runensängerin Karin Karaskeva hat welliges weißes Haar und trägt eine traditionelle wotische Tracht der Gegend und eine wunderschön bestickte Kopfbedeckung. Auf dem Schoß hat sie eine Strickarbeit, die ihre Hände beim Singen stets beschäftigt. Sie strickt warme Kleider für ihr neugeborenes Urenkelkind. Karin kennt Hunderte von Geschichten über Vaesen, mächtige Menschen und Zauberer sowie örtliche Schöpfungsmythen. Karin geriet auf dem Weg zum Hof ihrer Familie in den Schneesturm und sitzt im Speisesaal, als die Spielercharaktere ankommen. Sie kennt sich sehr gut mit den Domovoi aus und kann den Spielercharakteren Informationen über sie geben.",
   a:[2,3,4,4], f:[["Wachsamkeit",3],["Beobachtung",4]], z:[3,1], ausr:"Strickzeug", hier:"Speisesaal (Zimmer 7)"}
 },

 nock: {n:"Der Nisse Graufuß", p:84, x:"<img src=\"img/som/winter_eroeffnung.webp\" alt=\"\" style=\"float:right;width:150px;margin:0 0 8px 12px\">Graufuß hat die Werte und Eigenschaften eines gewöhnlichen Nisse – Werte im Grundregelwerk S. 148 (<a class=\"lnk\" onclick=\"go('vaesen/nisse')\">Nisse</a>). Er erscheint als kleiner alter Mann in hellgrauer Kleidung und gestrickter Mütze, mit bernsteinfarbenen Augen und langem, geflochtenem Bart, oder als langhaarige graue Katze. Er lässt sich mit Brei, Brot oder Milch und ein wenig Aufmerksamkeit besänftigen, mit Spinnenseide binden und mit einem Nagel aus einem verfallenen Bauernhaus, durchs Herz getrieben, töten – das bringt jedoch Unheil über das Gasthaus."},

 kaesten: [
  {t:"Ein Mittwinternachtstraum", p:74, x:"Der Schnee fällt immer schneller. Die Kälte ist unerbittlich, und deine Finger und Zehen sind schon taub. Wo sind alle? Plötzlich siehst du etwas, das sich ein Stück weiter vorn bewegt. Du gehst ihm nach. Das einzige Geräusch ist das deines Atems und deiner Schritte, während du dich durch den Schnee kämpfst. Vor dir liegt eine Lichtung, und im Licht siehst du eine große Gestalt in einem eisblauen Mantel auf dich zukommen. Eine Stimme spricht zu dir. Du kannst die Worte nicht verstehen, außer „… in mein Reich eingedrungen.“ Plötzlich wird dir wärmer, und ein herrliches Gefühl breitet sich in deinem Körper aus. Unfähig, noch einen Schritt zu tun, setzt du dich auf einen Stein. Du nimmst Hut und Handschuhe ab. Vor deinem inneren Auge siehst du die Weihnachtsfeste deiner Kindheit, wie du in warme Felle gehüllt auf dem Weg zur Kirche lagst. Den Klang der Stimmen deiner Eltern und der Pferde, die den Schlitten durch den Schnee ziehen. Das Licht der Laterne, die auf dem Schlitten hin und her schwingt. In deiner Hand ein Stück warmes Brot, das deine Mutter dir vor der Abreise gegeben hat… Vielleicht solltest du einfach hierbleiben?"}
 ],

 ho: [
  {id:"4a", t:"Handout 4A", u:"Brief von Graf Konstantin Konstantinowitsch", paper:"ho_4a", form:"brief", klein:1},
  {id:"4b", t:"Handout 4B", u:"Esters Tagebuch", paper:"ho_4b", form:"tagebuch", klein:1, x:"<b>17. Juni.</b> Vor zwei Wochen hat Ilya mir einen Heiratsantrag gemacht. Mir blieb nichts anderes übrig, als ihn abzuweisen. Er wollte mich aus dem Gasthaus fort in ein Leben in Sankt Petersburg mitnehmen. Er versteht es nicht. Ich habe kalt geantwortet, obwohl es mir das Herz brach. Ilya hatte mir einen wunderschönen silbernen Kamm gekauft. Er muss ein Vermögen gekostet haben. Ich sagte, ich habe bereits einen anderen Freund. In gewisser Weise habe ich das, schon immer. Und Axel braucht mich hier. Das Gasthaus bedeutet mir alles, und ich will alles in meiner Macht Stehende tun, unser Erbe zu bewahren. Ilyas Miene verfinsterte sich wie ein Gewitter über dem Wald im Sommer, und er verließ den Hof. Er ist nicht zurückgekehrt. Nachts, wenn es still im Haus wird, frage ich mich, ob ich die richtige Wahl getroffen habe."},
  {id:"4c", t:"Handout 4C", u:"Die Tarotkarten: Der Stern · Drei der Schwerter · Der Eremit", paper:"ho_4c", form:"bild"}
 ]
};
